//! Text for the deck faces: draw with ellipsis, measure, wrap.
//!
//! Glyphs come from the 4 bpp Noto Sans atlases in `font_data` (generated by
//! `tools/generate-ui-fonts.py`). A run is culled against the band before any
//! pixel work: by its line box in y, then per glyph in x, then row by row.
//! `bg = Some` writes a 16-step fg/bg ramp straight into the band rows;
//! `bg = None` blends each pixel over what is there (about 3x the cost).
//! Chinese and Japanese use the shared, scaled 2 bpp atlas in `font_cjk`. Codepoints
//! missing from both atlases draw as the replacement box.
use super::font_cjk;
use super::font_data::{FontData, Glyph, FONTS, FONT_COUNT, REPLACEMENT};
use super::theme::{font_spec, FontSpec, RAMP};
use crate::display::Band;
use embedded_graphics::{
    pixelcolor::{raw::RawU16, Rgb565, Rgb888},
    prelude::*,
};

pub use super::theme::Font;

const _: () = assert!(FONT_COUNT == RAMP.len());

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Align {
    /// `x` is the left edge of the text.
    Left,
    /// `x` is its centre.
    Center,
    /// `x` is its right edge.
    Right,
}

pub const ELLIPSIS: char = '\u{2026}';

const FAR: i32 = 1 << 20;

static EMPTY: Glyph = Glyph { offset: 0, cp: 0, advance: 0, left: 0, top: 0, w: 0, h: 0 };

fn data(font: Font) -> &'static FontData {
    &FONTS[font as usize]
}

/// The glyph for `c`, or the replacement box. ASCII is indexed directly (the
/// generator emits it first, in order); the rest is a binary search.
fn glyph(data: &'static FontData, c: char) -> Glyph {
    let cp = c as u32;
    let glyphs = data.glyphs;
    let found = if (0x20..0x7F).contains(&cp) {
        glyphs.get(cp as usize - 0x20).filter(|g| g.cp as u32 == cp)
    } else if cp <= 0xFFFF {
        glyphs.binary_search_by_key(&(cp as u16), |g| g.cp).ok().and_then(|i| glyphs.get(i))
    } else {
        None
    };
    found.copied()
        .or_else(|| font_cjk::source(cp).map(|g| font_cjk::scaled(g, data.px)))
        .or_else(|| glyphs.binary_search_by_key(&REPLACEMENT, |g| g.cp).ok().map(|i| glyphs[i]))
        .unwrap_or(EMPTY)
}

/// Pen advance in half pixels: the glyph's plus the face's tracking.
fn step(spec: &FontSpec, glyph: Glyph) -> i32 {
    glyph.advance as i32 * 2 + spec.tracking_half_px as i32
}

const fn px(half: i32) -> i32 {
    (half + 1) >> 1
}

/// How much of `text` goes on one line of `max_w`: (bytes of `text` to draw,
/// whether "…" follows them, width in half pixels). A run wider than `max_w`
/// keeps the longest prefix that leaves room for the ellipsis, without a
/// trailing space.
fn fit(data: &'static FontData, spec: &FontSpec, text: &str, max_w: i32) -> (usize, bool, i32) {
    if max_w <= 0 {
        return (0, false, 0);
    }
    let max_half = max_w.saturating_mul(2);
    let mut width: i32 = 0;
    for c in text.chars() {
        width = width.saturating_add(step(spec, glyph(data, c)));
    }
    if width <= max_half {
        return (text.len(), false, width);
    }
    let ellipsis = step(spec, glyph(data, ELLIPSIS));
    if ellipsis > max_half {
        return (0, false, 0);
    }
    let mut acc: i32 = 0;
    let mut best = (0, 0);
    for (at, c) in text.char_indices() {
        let step = step(spec, glyph(data, c));
        if acc.saturating_add(step).saturating_add(ellipsis) > max_half {
            break;
        }
        acc += step;
        if c != ' ' {
            best = (at + c.len_utf8(), acc);
        }
    }
    (best.0, true, best.1 + ellipsis)
}

/// RGB565 bytes of fg over bg at each 4-bit coverage, as the band stores them.
fn ramp(fg: u32, bg: u32) -> [[u8; 2]; 16] {
    let mut ramp = [[0; 2]; 16];
    for (a, entry) in ramp.iter_mut().enumerate() {
        let t = a as u32 * 17;
        let channel = |shift: u32| ((((bg >> shift) & 255) * (255 - t) + ((fg >> shift) & 255) * t) / 255) as u8;
        let color: Rgb565 = Rgb888::new(channel(16), channel(8), channel(0)).into();
        *entry = RawU16::from(color).into_inner().to_le_bytes();
    }
    ramp
}

/// One glyph bitmap with its top-left at (gx, gy), clipped to the band.
fn blit(band: &mut Band, atlas: &[u8], glyph: &Glyph, gx: i32, gy: i32, fg: u32, ramp: Option<&[[u8; 2]; 16]>) {
    let clip = band.bounding_box();
    let x0 = gx.max(clip.top_left.x);
    let x1 = (gx + glyph.w as i32).min(clip.top_left.x + clip.size.width as i32);
    let y0 = gy.max(clip.top_left.y);
    let y1 = (gy + glyph.h as i32).min(clip.top_left.y + clip.size.height as i32);
    if x0 >= x1 || y0 >= y1 {
        return;
    }
    let stride = (glyph.w as usize + 1) / 2;
    let first = (x0 - gx) as usize;
    for y in y0..y1 {
        let start = glyph.offset as usize + (y - gy) as usize * stride;
        let Some(row) = atlas.get(start..start + stride) else {
            return;
        };
        let nibble = |sx: usize| {
            let byte = row.get(sx / 2).copied().unwrap_or(0);
            if sx & 1 == 0 {
                byte >> 4
            } else {
                byte & 15
            }
        };
        match ramp {
            Some(ramp) => {
                let Some(out) = band.row_mut(y, x0, x1) else {
                    continue;
                };
                for (i, px) in out.chunks_exact_mut(2).enumerate() {
                    let a = nibble(first + i);
                    if a != 0 {
                        px.copy_from_slice(&ramp[a as usize]);
                    }
                }
            }
            None => {
                for sx in first..(x1 - gx) as usize {
                    let a = nibble(sx);
                    if a != 0 {
                        band.blend_px(gx + sx as i32, y, fg, a * 17);
                    }
                }
            }
        }
    }
}

/// CJK uses the same clipping and blending contract as the Latin atlas.
#[allow(clippy::too_many_arguments)]
fn blit_cjk(band: &mut Band, source: &Glyph, glyph: &Glyph, gx: i32, gy: i32, fg: u32, ramp: Option<&[[u8; 2]; 16]>) {
    let clip = band.bounding_box();
    let x0 = gx.max(clip.top_left.x);
    let x1 = (gx + glyph.w as i32).min(clip.top_left.x + clip.size.width as i32);
    let y0 = gy.max(clip.top_left.y);
    let y1 = (gy + glyph.h as i32).min(clip.top_left.y + clip.size.height as i32);
    if x0 >= x1 || y0 >= y1 {
        return;
    }
    for y in y0..y1 {
        let coverage = |x: i32| font_cjk::coverage(source, glyph, (x - gx) as usize, (y - gy) as usize);
        if let Some(ramp) = ramp {
            if let Some(out) = band.row_mut(y, x0, x1) {
                for (i, pixel) in out.chunks_exact_mut(2).enumerate() {
                    let a = coverage(x0 + i as i32);
                    if a != 0 { pixel.copy_from_slice(&ramp[a as usize]); }
                }
            }
        } else {
            for x in x0..x1 {
                let a = coverage(x);
                if a != 0 { band.blend_px(x, y, fg, a * 17); }
            }
        }
    }
}

/// Draw one line. `baseline_y` is the text baseline. `bg`: `Some(colour)` when
/// the text sits on that flat colour (fast path: a 16-step fg/bg ramp, no
/// framebuffer reads), `None` to blend over whatever is there. Text wider
/// than `max_w` ends in "…". Returns the width of the run in pixels, whether
/// or not this band shows any of it, so callers can chain runs in every band.
///
/// Culls against `band.bounding_box()` before doing any pixel work.
#[allow(clippy::too_many_arguments)]
pub fn draw(
    band: &mut Band,
    font: Font,
    x: i32,
    baseline_y: i32,
    text: &str,
    fg: u32,
    bg: Option<u32>,
    max_w: i32,
    align: Align,
) -> i32 {
    let data = data(font);
    let spec = font_spec(font);
    let (end, ellipsis, width_half) = fit(data, &spec, text, max_w);
    let width = px(width_half).min(FAR);
    // Far off-screen positions cull like any other; the clamps keep the pen
    // arithmetic below in range.
    let (x, baseline_y) = (x.clamp(-FAR, FAR), baseline_y.clamp(-FAR, FAR));
    let clip = band.bounding_box();
    let top = clip.top_left.y;
    let bottom = top + clip.size.height as i32;
    let above = (data.above as i32).max(font_cjk::above(data.px));
    let below = (data.below as i32).max(font_cjk::below(data.px));
    if width == 0 || baseline_y - above >= bottom || baseline_y + below <= top {
        return width;
    }
    let left = clip.top_left.x;
    let right = left + clip.size.width as i32;
    let mut pen_half = 2 * match align {
        Align::Left => x,
        Align::Center => x - width / 2,
        Align::Right => x - width,
    };
    let ramp = bg.map(|bg| ramp(fg, bg));
    let shown = text.get(..end).unwrap_or("");
    for c in shown.chars().chain(ellipsis.then_some(ELLIPSIS)) {
        let glyph = glyph(data, c);
        let pen = pen_half >> 1;
        pen_half += step(&spec, glyph);
        let gx = pen + glyph.left as i32;
        // Not `break` past the right edge: a later glyph's negative bearing
        // may still reach back into the clip.
        if glyph.w == 0 || glyph.h == 0 || gx + glyph.w as i32 <= left || gx >= right {
            continue;
        }
        let gy = baseline_y - glyph.top as i32;
        if let Some(source) = font_cjk::source(glyph.cp as u32) {
            blit_cjk(band, &source, &glyph, gx, gy, fg, ramp.as_ref());
        } else {
            blit(band, data.atlas, &glyph, gx, gy, fg, ramp.as_ref());
        }
    }
    width
}

/// Width of `text` on one line, without any limit.
pub fn measure(font: Font, text: &str) -> i32 {
    let data = data(font);
    let spec = font_spec(font);
    px(text.chars().fold(0i32, |w, c| w.saturating_add(step(&spec, glyph(data, c)))))
}

/// Baseline-to-baseline distance of wrapped text.
pub fn line_height(font: Font) -> i32 {
    data(font).line_height as i32
}

/// Baseline down from the top of a line box.
pub fn ascent(font: Font) -> i32 {
    data(font).ascent as i32
}

/// Accents and CJK glyphs may extend above the nominal line box.
pub fn top_overhang(font: Font) -> i32 {
    let face = data(font);
    (i32::from(face.above).max(font_cjk::above(face.px)) - i32::from(face.ascent)).max(0)
}

/// Complete lines that fit, including the last line's descenders.
pub fn lines_in_height(font: Font, height: i32) -> usize {
    let face = data(font);
    let first = face.ascent as i32 + face.below as i32;
    if height < first {
        0
    } else {
        1 + ((height - first) / face.line_height as i32) as usize
    }
}

/// Greedy word wrap into at most `max_lines` lines of at most `max_w`. `f`
/// gets (line index, line, truncated); `truncated` marks a last line that
/// leaves text over, which the caller draws with `max_w` so it ends in "…".
/// Breaks at spaces and newlines; a word wider than a line breaks inside.
pub fn wrap(
    font: Font,
    text: &str,
    max_w: i32,
    max_lines: usize,
    f: &mut dyn FnMut(usize, &str, bool),
) {
    let data = data(font);
    let spec = font_spec(font);
    let max_half = max_w.max(0).saturating_mul(2);
    let mut rest = text.trim_start_matches(' ');
    let mut line = 0;
    while !rest.is_empty() && line < max_lines {
        let mut acc: i32 = 0;
        let mut space = None;
        let (mut end, mut next, mut forced) = (rest.len(), rest.len(), false);
        for (at, c) in rest.char_indices() {
            if c == '\n' {
                (end, next, forced) = (at, at + 1, true);
                break;
            }
            if c == ' ' {
                space = Some(at);
            }
            let step = step(&spec, glyph(data, c));
            if at > 0 && acc.saturating_add(step) > max_half {
                (end, next) = match space {
                    Some(at) => (at, at + 1),
                    None => (at, at),
                };
                break;
            }
            acc += step;
        }
        let shown = rest.get(..end).unwrap_or("").trim_end_matches(' ');
        let remainder = rest.get(next..).unwrap_or("").trim_start_matches(' ');
        if line + 1 == max_lines && !remainder.is_empty() {
            f(line, if forced { shown } else { rest }, true);
        } else {
            f(line, shown, false);
        }
        rest = remainder;
        line += 1;
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::{string::String, vec::Vec};

    fn lines(text: &str, max_w: i32, max_lines: usize) -> Vec<(String, bool)> {
        let mut out = Vec::new();
        wrap(Font::Body, text, max_w, max_lines, &mut |index, line, cut| {
            assert_eq!(index, out.len());
            out.push((String::from(line), cut));
        });
        out
    }

    #[test]
    fn wrap_breaks_at_words_and_marks_a_truncated_last_line() {
        let w = measure(Font::Body, "alpha beta");
        assert_eq!(
            lines("alpha beta gamma", w, 4),
            [("alpha beta".into(), false), ("gamma".into(), false)]
        );
        assert_eq!(
            lines("alpha beta gamma delta", w, 2),
            [("alpha beta".into(), false), ("gamma delta".into(), true)]
        );
        assert_eq!(lines("alpha  beta", measure(Font::Body, "alpha "), 3).len(), 2);
        assert_eq!(lines("one\ntwo", w, 3), [("one".into(), false), ("two".into(), false)]);
        assert_eq!(lines("one\ntwo three", w, 1), [("one".into(), true)]);
        assert!(lines("", w, 3).is_empty());
        assert!(lines("text", w, 0).is_empty());
        for (line, _) in lines("alpha beta gamma delta", w, 9) {
            assert!(measure(Font::Body, &line) <= w);
        }
    }

    #[test]
    fn wrap_hard_breaks_an_over_long_word_and_never_loops() {
        let w = measure(Font::Body, "abcdefghij");
        let out = lines("abcdefghijklmnop qr", w, 3);
        assert_eq!(out.len(), 2);
        assert!(out[0].0.starts_with("abcdefghij") && !out[0].1);
        assert!(out[0].0.len() <= 12 && out[1].0.ends_with(" qr"));
        // Wide characters never split and a zero width still terminates.
        assert_eq!(lines("\u{e9}\u{e9}", 0, 2).len(), 2);
        assert_eq!(lines("\u{e9}\u{e9}\u{e9}", 0, 2), [("\u{e9}".into(), false), ("\u{e9}\u{e9}".into(), true)]);
        assert_eq!(lines("ab cd", -5, 4).len(), 4);
    }

    #[test]
    fn measure_and_metrics_are_positive_for_the_whole_ramp() {
        for spec in RAMP {
            assert!(measure(spec.font, "M") > 0);
            assert_eq!(measure(spec.font, ""), 0);
            assert!(line_height(spec.font) > ascent(spec.font));
            assert!(ascent(spec.font) > 0);
            assert_eq!(data(spec.font).px, spec.px, "{:?}: theme and atlas disagree", spec.font);
            assert!(data(spec.font).above as i32 >= ascent(spec.font) - 2);
        }
        // Proportional: a wide glyph advances more than a narrow one.
        assert!(measure(Font::Body, "W") > measure(Font::Body, "i"));
        // Tracking: the label face adds 1.5 px per glyph.
        let label = data(Font::Label);
        let advances: i32 = "AGENTS".chars().map(|c| glyph(label, c).advance as i32).sum();
        assert_eq!(measure(Font::Label, "AGENTS"), advances + 9);
    }

    #[test]
    fn glyph_table_is_sorted_with_ascii_first_and_a_replacement_in_every_font() {
        for (index, data) in FONTS.iter().enumerate() {
            for (i, g) in data.glyphs.iter().enumerate() {
                if i < 95 {
                    assert_eq!(g.cp as usize, 0x20 + i, "font {index}: ASCII must lead");
                }
                if i > 0 {
                    assert!(data.glyphs[i - 1].cp < g.cp, "font {index}: unsorted at {i}");
                }
                let end = g.offset as usize + g.h as usize * ((g.w as usize + 1) / 2);
                assert!(end <= data.atlas.len(), "font {index}: glyph {:x} past the atlas", g.cp);
            }
            let replacement = glyph(data, '\u{fffd}');
            assert_eq!(replacement.cp, REPLACEMENT);
            assert!(replacement.w > 0 && replacement.h > 0);
        }
        let body = data(Font::Body);
        // The whole coverage list resolves to a real glyph, not the box.
        for c in "aZ09\u{a0}\u{e9}\u{ff}\u{100}\u{17f}\u{b7}\u{d7}\u{2013}\u{2014}\u{2018}\u{2019}\u{201c}\u{201d}\u{2026}\u{2039}\u{203a}\u{2190}\u{2191}\u{2192}\u{2193}\u{21b5}\u{2713}\u{23ce}".chars() {
            assert_eq!(glyph(body, c).cp as u32, c as u32, "{c:?} missing");
        }
        // Everything else is the replacement box, from controls to emoji.
        for c in ['\n', '\t', '\u{7f}', '\u{3a9}', '\u{1f600}', char::MAX] {
            assert_eq!(glyph(body, c).cp, REPLACEMENT, "{c:?}");
        }
    }

    #[test]
    fn chinese_uses_full_width_metrics_and_wraps_at_character_boundaries() {
        for spec in RAMP {
            for c in "中文简体繁體，。".chars() {
                assert_eq!(glyph(data(spec.font), c).cp as u32, c as u32);
            }
            assert_eq!(measure(spec.font, "中文"), 2 * spec.px as i32 + spec.tracking_half_px as i32);
            let text = "中文字体顯示測試";
            let width = measure(spec.font, "中文");
            let mut joined = String::new();
            wrap(spec.font, text, width, 20, &mut |_, line, cut| {
                assert!(!cut);
                assert!(measure(spec.font, line) <= width);
                joined.push_str(line);
            });
            assert_eq!(joined, text);
            let (end, cut, fitted) = fit(data(spec.font), &spec, text, width);
            assert!(text.is_char_boundary(end) && cut && px(fitted) <= width);
        }
    }

    #[test]
    fn japanese_uses_kana_fallback_and_wraps_at_character_boundaries() {
        let text = "日本語の設定です。カタカナも表示できます。";
        for spec in RAMP {
            for c in text.chars().chain("ｶﾀｶﾅﾞﾟ".chars()) {
                assert_eq!(glyph(data(spec.font), c).cp as u32, c as u32, "{c:?} missing");
            }
            let width = measure(spec.font, "日本");
            let mut joined = String::new();
            wrap(spec.font, text, width, 40, &mut |_, line, cut| {
                assert!(!cut);
                assert!(measure(spec.font, line) <= width);
                joined.push_str(line);
            });
            assert_eq!(joined, text);
            let (end, cut, fitted) = fit(data(spec.font), &spec, text, width);
            assert!(text.is_char_boundary(end) && cut && px(fitted) <= width);
        }
    }

    #[test]
    fn fit_keeps_the_longest_prefix_with_room_for_the_ellipsis() {
        let data = data(Font::Row);
        let spec = font_spec(Font::Row);
        let full = measure(Font::Row, "Compiling openmicro");
        assert_eq!(fit(data, &spec, "Compiling openmicro", full), (19, false, full * 2));
        let (end, cut, width) = fit(data, &spec, "Compiling openmicro", full - 1);
        assert!(cut && end < 19 && px(width) <= full - 1);
        assert!(!"Compiling openmicro"[..end].ends_with(' '));
        assert_eq!(fit(data, &spec, "anything", 0), (0, false, 0));
        assert_eq!(fit(data, &spec, "anything", -7), (0, false, 0));
        let dots = measure(Font::Row, "\u{2026}");
        assert_eq!(fit(data, &spec, "anything wide", dots), (0, true, dots * 2));
        assert_eq!(fit(data, &spec, "anything wide", dots - 1), (0, false, 0));
        assert_eq!(fit(data, &spec, "", 100), (0, false, 0));
    }
}
